(()=>{const el=id=>document.getElementById(id),n=id=>Number(el(id).value)||0,f=(v,d=1)=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:d}).format(v);function update(){const v=n('calc-labs')*n('calc-hplc-count')*n('calc-flow')*60*n('calc-hours-day')*n('calc-days-week')*n('calc-weeks-year')/1000,fr=n('calc-recovery')/100,wr=n('calc-waste-reduction')/100,tr=n('prep-reduction')/100,h=n('prep-hours')*n('calc-labs')*n('calc-weeks-year'),m=v*n('calc-solvent-cost'),d=v*n('calc-disposal-cost'),l=h*(n('prep-rate')/Number(document.getElementById('prep-paid-hours').value));const data={fresh:[v,v*(1-fr),'L'],waste:[v,v*(1-wr),'L'],hours:[h,h*(1-tr),'h'],material:[m,m*(1-fr),'€'],disposal:[d,d*(1-wr),'€'],labour:[l,l*(1-tr),'€'],cash:[m+d,m*(1-fr)+d*(1-wr),'€'],total:[m+d+l,m*(1-fr)+d*(1-wr)+l*(1-tr),'€'],production:[v*3.69/1000,v*(1-fr)*3.69/1000,'t CO₂e'],treatment:[v*1.57/1000,v*(1-wr)*1.57/1000,'t CO₂e'],carbon:[v*5.26/1000,v*((1-fr)*3.69+(1-wr)*1.57)/1000,'t CO₂e']};for(const[k,[base,after,u]]of Object.entries(data)){[base,after,base-after].forEach((x,i)=>{let text=u==='€'?'€'+f(x,2):f(x,u==='t CO₂e'?2:1)+' '+u;if(k==='waste')text+=' · ≈ '+f(x/1000,2)+' t';if((k==='labour'||k==='hours')&&!n('prep-hours'))text='Enter preparation hours';else if(k==='labour'&&!(n('prep-rate')/Number(document.getElementById('prep-paid-hours').value)))text='Enter annual salary';if(k==='total'&&(!n('prep-hours')||!(n('prep-rate')/Number(document.getElementById('prep-paid-hours').value))))text+=' + labour not entered';document.querySelector('[data-compare="'+k+'-'+i+'"]').textContent=text;});}}document.addEventListener('resolve-model',update);['prep-hours','prep-rate','prep-reduction'].forEach(id=>el(id).addEventListener('input',update));el('calc-reset').addEventListener('click',update);update();})();